sql.insert:
INSERT INTO save_metadata (
  singleton_id, schema_version, base_content_version, created_utc_seconds,
  updated_utc_seconds, logical_utc_seconds
) VALUES (
  1, @schema_version, @base_content_version, @created_utc_seconds,
  @updated_utc_seconds, @logical_utc_seconds
);

sql.update:
UPDATE save_metadata
SET base_content_version = @base_content_version
WHERE singleton_id = 1;
